#!/usr/bin/env python3
"""Build a single-file hybrid: incumbent main.py opening, then FQ4 from a hand-over day.

The incumbent source stays untouched at the top of the file. FQ4 runs in its
own module namespace so none of its names can shadow incumbent globals. The
new entry point is defined last, which is what Kaggle's loader selects.
"""
from __future__ import annotations
import argparse, json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

WRAPPER = '''

# ---- FQ4 hand-over wrapper (generated by scripts/build_fq4_hybrid.py) ----
import types as _fq4_types
_FQ4_SOURCE = {source!r}
_FQ4_MODULE = _fq4_types.ModuleType("fq4_embedded")
exec(compile(_FQ4_SOURCE, "fq4_embedded", "exec"), _FQ4_MODULE.__dict__)
_FQ4_CONFIG = {config!r}
_FQ4_HANDOVER_STEP = {handover}
_FQ4_INCUMBENT = [_v for _v in list(globals().values()) if callable(_v)][-1]  # the entry Kaggle would select
_FQ4_BOTS = {{}}


def fq4_hybrid_agent(observation, configuration=None):
    step = int(_FQ4_MODULE.g(observation, "step", 0))
    me = int(_FQ4_MODULE.g(observation, "player", 0))
    if step == 0:
        _FQ4_BOTS.pop(me, None)
    if step < _FQ4_HANDOVER_STEP:
        return _FQ4_INCUMBENT(observation, configuration)
    bot = _FQ4_BOTS.get(me)
    if bot is None:
        bot = _FQ4_MODULE.FQ4(_FQ4_CONFIG)
        _FQ4_BOTS[me] = bot
    try:
        return bot.act(observation)
    except Exception:
        return {{"farmer": ["PASS"], "hands": [], "market": []}}
'''


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--incumbent", default=str(ROOT / "main.py"))
    p.add_argument("--fq4", default=str(ROOT / "agents/fq4.py"))
    p.add_argument("--handover-day", type=int, default=10)
    p.add_argument("--config", default="{}")
    p.add_argument("--output", required=True)
    a = p.parse_args()
    inc = Path(a.incumbent).read_text()
    src = Path(a.fq4).read_text()
    out = inc + WRAPPER.format(source=src, config=json.loads(a.config), handover=a.handover_day * 24)
    Path(a.output).parent.mkdir(parents=True, exist_ok=True)
    Path(a.output).write_text(out)
    print("wrote", a.output, len(out))


if __name__ == "__main__":
    main()
